#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_node_nonzero_ct_zero_wt_nonzero_tat(void) {
    // Setup: Build a linked list with at least two nodes.
    // We need a non-head node to update.
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial state of node with ID 2 (non-head, second node).
    node *ptr = root->next;
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(2, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT); // Initial CT is 0
    TEST_ASSERT_EQUAL_INT(0, ptr->WT); // Initial WT is 0
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT); // Initial TAT is 0

    // Test: Update non-head node (ID=2) with ct != 0, wt == 0, tat != 0.
    // This matches path 11 conditions:
    // - ptr != NULL && ptr->ID != id (head node ID is 1, we search for 2)
    // - ct != 0 (true, ct=100)
    // - wt != 0 (false, wt=0)
    // - tat != 0 (true, tat=50)
    int id_to_update = 2;
    int new_ct = 100;
    int new_wt = 0;
    int new_tat = 50;
    update(&root, id_to_update, new_ct, new_wt, new_tat);

    // Assertions: Verify only CT and TAT were updated, WT remains unchanged.
    ptr = root->next; // Get node with ID 2 again
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(2, ptr->ID);
    TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT); // WT should still be 0
    TEST_ASSERT_EQUAL_INT(new_tat, ptr->TAT);

    // Verify other nodes are unchanged.
    TEST_ASSERT_EQUAL_INT(1, root->ID);
    TEST_ASSERT_EQUAL_INT(0, root->CT);
    TEST_ASSERT_EQUAL_INT(0, root->WT);
    TEST_ASSERT_EQUAL_INT(0, root->TAT);

    node *third = root->next->next;
    TEST_ASSERT_NOT_NULL(third);
    TEST_ASSERT_EQUAL_INT(3, third->ID);
    TEST_ASSERT_EQUAL_INT(0, third->CT);
    TEST_ASSERT_EQUAL_INT(0, third->WT);
    TEST_ASSERT_EQUAL_INT(0, third->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_node_nonzero_ct_zero_wt_nonzero_tat);
    return UNITY_END();
}

